(function(){
'use strict';
const C=window.COURSE,E=window.BioEngine,$=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg class="icon" aria-hidden="true"><use href="#i-${n}"></use></svg>`;
const chapter=id=>C.chapters.find(x=>x.id===id);
let state=E.fresh(),storageOK=true,route='',review=null,diagnosticPos=0,shown=new Set(),spoken=new Set(),examChecks={},reviewFilter='weak',reviewChapter='',examFilter='',day=1,courseFilter='';
try{const raw=localStorage.getItem(E.KEY);if(raw)state=E.validateImport(JSON.parse(raw),C);localStorage.setItem(E.KEY,JSON.stringify(state));}catch(error){storageOK=false;}
function save(){try{localStorage.setItem(E.KEY,JSON.stringify(state));storageOK=true;$('#storage-warning').hidden=true;}catch(error){storageOK=false;$('#storage-warning').hidden=false;}$('#save-status').textContent=storageOK?'Sparat på den här enheten':'Lagring är inte tillgänglig';}
$('#storage-warning').hidden=storageOK;
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4400);}
const button=(label,path,cls='')=>`<a class="button ${cls}" href="#${path}">${label}${icon('arrow')}</a>`;
const title=(eyebrow,h,p)=>`<div class="page-heading"><span class="eyebrow">${eyebrow}</span><h1>${h}</h1>${p?`<p>${p}</p>`:''}</div>`;
const pill=(level='must')=>`<span class="pill ${level}">${level==='must'?'MÅSTE KUNNA':level==='deep'?'BÖR KUNNA':'OM TID FINNS'}</span>`;
const back=(name,path)=>`<a class="back" href="#${path}">${icon('arrow')}${name}</a>`;
const formatMinutes=n=>n>=60?`${Math.floor(n/60)} h ${n%60?`${n%60} min`:''}`.trim():`${n} min`;
function navigate(path){location.hash=path;}
function summaryStats(){const secure=C.cards.filter(x=>state.cards[x.id]?.rating===2).length;const rated=C.cards.filter(x=>state.cards[x.id]).length;const exams=Object.keys(state.exams).length;return {secure,rated,exams};}
function statsHTML(){const s=summaryStats();return `<section class="stats" aria-label="Din självskattade progression"><div class="stat"><span class="stat-label">Trygga kärnfrågor</span><strong>${s.secure}<small> / 28 självskattade</small></strong><span class="mini-icon">${icon('check')}</span><div class="progress-track" role="progressbar" aria-label="Självskattat säkra kärnfrågor" aria-valuemin="0" aria-valuemax="28" aria-valuenow="${s.secure}"><span style="width:${s.secure/28*100}%"></span></div></div><div class="stat"><span class="stat-label">Effektiv studietid kvar</span><strong data-remaining-display>${formatMinutes(E.remain(state))}</strong><span class="mini-icon">${icon('clock')}</span><button class="quiet fine" data-action="settings" style="padding:2px 0;display:block;min-height:30px">Anpassa till din tid ↗</button></div><div class="stat"><span class="stat-label">Egna svar, självbedömda</span><strong>${s.exams}<small> / ${C.exams.length} öppna provfrågor</small></strong><span class="mini-icon">${icon('pen')}</span><p class="fine" style="margin:7px 0 0">Kvalitet före antal.</p></div></section>`;}
function cellArt(){return `<div class="hero-art"><svg viewBox="0 0 380 295" role="img" aria-label="Förenklad eukaryot cell med kärna, mitokondrier, ER och membran. Länkarna öppnar motsvarande förklaring."><defs><pattern id="dot-grid" width="19" height="19" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="#dce3d1"/></pattern></defs><rect width="380" height="295" fill="url(#dot-grid)"/><path d="M89 66C121 15 248 26 291 64S352 182 304 230 158 282 91 236 39 121 89 66Z" fill="#e0e9c9" stroke="#719064" stroke-width="1.7"/><path d="M96 72C130 25 245 36 285 72S339 178 298 222 160 270 99 229 49 125 96 72Z" fill="#edf1de" stroke="#a3b88b" stroke-width="1"/><g fill="none" stroke="#c2d1a5" stroke-width="3" stroke-linecap="round"><path d="M105 110q25-38 50-24m-55 37q22-38 53-25m-48 40q22-39 50-26m-42 39q21-29 45-22"/><path d="M127 209q30 12 51-2m-51 12q30 12 51-2m-47 12q26 12 49-2"/></g><a href="#chapter/celler"><circle cx="201" cy="134" r="44" fill="#cfdfae" stroke="#8da66b" stroke-width="1.5"/><circle cx="205" cy="138" r="17" fill="#a7c079"/><path d="M175 120q22-17 40 1m-40 27q10 16 27 14m12-54q15 3 19 19" fill="none" stroke="#a0b97a" stroke-width="1.3"/></a><g fill="#dfbd7d" stroke="#b99559" stroke-width="1.2"><a href="#chapter/celler"><ellipse cx="279" cy="124" rx="16" ry="28" transform="rotate(25 279 124)"/></a><ellipse cx="119" cy="182" rx="16" ry="25" transform="rotate(-35 119 182)"/></g><g stroke="#b18b4b" fill="none"><path d="m276 101-4 14 10 1-15 13 11 2-8 12M104 168l10 1-3 11 14-3-2 15 12-1"/></g><g fill="#adc28b"><circle cx="245" cy="196" r="9"/><circle cx="151" cy="72" r="5"/><circle cx="281" cy="179" r="6"/><circle cx="91" cy="145" r="4"/></g><g fill="#7c995c"><circle cx="142" cy="155" r="2"/><circle cx="150" cy="168" r="2"/><circle cx="261" cy="89" r="2"/><circle cx="257" cy="218" r="2"/><circle cx="178" cy="187" r="2"/><circle cx="302" cy="154" r="2"/></g><g stroke="#91a377" stroke-width=".8" fill="none"><path d="M218 121h65l30-28h49M113 181H58l-15 20H8M164 97H91L62 62H14M295 211l28 30h49"/></g><g fill="#59734d" font-family="Segoe UI, sans-serif" font-size="9"><text x="313" y="85">CELLKÄRNA</text><text x="9" y="216">MITOKONDRIE</text><text x="15" y="55">KORNIGT ER</text><text x="298" y="255">MEMBRAN</text></g></svg><div class="art-caption">STRUKTUR → FUNKTION → SAMBAND</div></div>`;}
function topicCard(c){const s=E.chapterStats(state,C,c.id);return `<a class="topic-link" href="#chapter/${c.id}"><span class="topic-number">${c.n}</span><div><h3>${c.title}</h3><p>${s.rated?`${s.secure}/4 trygga · ${s.missed?s.missed+' saknade poänger':'fortsätt förklara'}`:'Kärnmodell + 4 frågor'} · riktmärke ${c.minutes} min</p></div>${icon('arrow')}</a>`;}
function nextSession(){return C.sessions.find(s=>s.tasks.some(t=>!state.tasks[t[0]]))||null;}
function home(){const next=nextSession(),a=E.adaptive(state,C);if(a.mode==='minimum'&&state.diagnosed)return shortHome(a);return `<section class="hero"><div><span class="eyebrow">BIOLOGI 2 · DITT TVÅDAGARSPROGRAM</span><h1>Förstå sambanden.<br><span>Skriv bättre provsvar.</span></h1><p>Sju områden, en tydlig väg. Lär mekanismerna, plocka fram dem ur minnet och använd dem i egna resonemang.</p><div class="actions">${button(state.diagnosed?(next?'Fortsätt där du är':'Repetera det viktiga'):'Starta första passet',state.diagnosed?(next?'session/'+next.id:'review'):'session/1')}${button('Se din studieplan','plan','secondary')}</div></div>${cellArt()}</section>${statsHTML()}<div class="two-cols"><section class="next-card"><span class="eyebrow">${state.diagnosed?'DIN NÄSTA AKTIVITET':'BÖRJA HÄR · 10 MINUTER'}</span><h2>${state.diagnosed?(next?next.title:'Håll mekanismerna levande'):'Ta reda på vad du redan kan.'}</h2><p>${state.diagnosed?(next?next.goal:'Återkalla dina osäkra frågor och använd dem i ett nytt scenario.'):'Sju korta frågor visar var du ska lägga kraften. Förklara först med egna ord. Det är helt okej att markera ”Inte kan”.'}</p><div class="session-meta">${state.diagnosed&&next?`DAG ${next.day} · ${next.time} · ${next.effective} EFFEKTIVA MINUTER`:'EN FRÅGA PER OMRÅDE · UTAN BETYGSPOÄNG'}</div>${button(state.diagnosed?'Öppna nästa steg':'Gör snabbdiagnosen',state.diagnosed?(next?'session/'+next.id:'review'):'diagnostic','light')}</section><section class="card"><div class="small-intro">${icon('link')} DIN VIKTIGASTE TANKEMODELL</div><h3>Vad passerar?<br>Vad driver det?<br>Vad blir följden?</h3><p>En säker orsakskedja hjälper dig även när provfrågan ser helt ny ut.</p><a class="fine" href="#connections">Träna biologiska samband →</a></section></div><div class="section-top"><h2>Två dagar med plats för livet.</h2><a href="#plan">Hela schemat →</a></div><div class="schedule-preview"><div class="day-preview"><div class="day-title"><h3>Måndag 2 nov</h3><span>235 min effektivt</span></div><p>Grundmodeller, transport, mikrober och resistens.</p>${C.sessions.filter(x=>x.day===1).map(s=>`<div class="day-line"><span>${s.time.slice(0,5)}</span><i class="dot"></i><a href="#session/${s.id}">${s.title}</a></div>`).join('')}</div><div class="day-preview"><div class="day-title"><h3>Tisdag 3 nov</h3><span>125 min effektivt</span></div><p>Återkallning, växtcellen, egna provsvar och luckor.</p>${C.sessions.filter(x=>x.day===2).map(s=>`<div class="day-line"><span>${s.time.slice(0,5)}</span><i class="dot"></i><a href="#session/${s.id}">${s.title}</a></div>`).join('')}<p style="margin-top:17px">Fotboll 16:30–19:00. Sen kväll? Förkorta passet och behåll sömnen.</p></div></div><div class="section-top"><h2>Din biologiska verktygslåda.</h2><a href="#course">Utforska kursen →</a></div><div class="topic-grid">${C.chapters.map(topicCard).join('')}</div>${a.time<200?`<div class="info-strip space-top">${icon('clock')}Du har ${a.time} effektiva minuter kvar. Den anpassade planen prioriterar kärnmodeller och egna svar. <a href="#plan">Öppna planen</a></div>`:''}`;}
function shortHome(a){const t=a.tasks[0];return `${title('ANPASSAT EFTER DIN TID','En viktig sak i taget.',`Du har ${a.time} effektiva minuter kvar. Börja med kärnmodellen som planen prioriterar och kontrollera den utan stöd.`)}${statsHTML()}<section class="next-card"><span class="eyebrow">NÄSTA STEG · ${t?.minutes||0} MINUTER</span><h2>${t?.title||'Avsluta och återhämta dig.'}</h2><p>Alla sju områden finns kvar. Den korta planen väljer det som ryms nu och behåller utrymme för egna svar.</p>${button('Börja nu',t?.route||'plan','light')}</section><div class="actions space-top">${button('Se anpassad studieplan','plan','secondary')}${button('Mina kunskapsluckor','progress','secondary')}</div>`;}
function plan(){const a=E.adaptive(state,C);return `${title('TID ÄR EN RESURS','En plan som går att genomföra.','Standard: 235 effektiva minuter på måndagen och 125 på tisdagen. Alla angivna pauser ligger utanför de 360 effektiva minuterna.')}<div class="programme" aria-label="Välj tid som utgångspunkt">${[['minimum','Minimiprogram','180 min · alla sju kärnor',180],['standard','Standardprogram','360 min · huvudspåret',360],['extra','Extraprogram','450 min · utanför sex timmar',450]].map(([id,label,sub,min])=>`<button data-action="programme" data-minutes="${min}" aria-pressed="${a.mode===id}"><strong>${label}</strong><small>${sub}</small></button>`).join('')}</div><p class="fine">Knapparna anger hur mycket effektiv tid du har kvar från nu. Timern drar sedan av faktisk fokustid. Standardprogrammet är högst 360 effektiva minuter. Extraprogrammet är ett uttryckligt val av mer tid och ingår inte i sextimmarsprogrammet.</p><section class="card"><div class="section-top" style="margin-top:0"><h2>Din prioritering just nu</h2><button class="button secondary small" data-action="settings">Ändra tid</button></div><p>${a.time} minuter fördelas efter självskattade luckor, missade provpoänger och vilka modeller som behövs för resten. Detta är ett förslag, inte en automatisk kunskapsbedömning.</p><ol class="task-list">${a.tasks.map(t=>`<li><div><a href="#${t.route}">${t.title}</a><small>${t.minutes} min · ${t.priority==='must'?'MÅSTE KUNNA':'VIKTIG FÖRDJUPNING'}</small></div><a class="button secondary small" href="#${t.route}">Öppna →</a></li>`).join('')}</ol>${a.time<100?'<p class="fine">Tiden räcker inte till lika mycket i alla områden. Börja med den svagaste mekanismen och behåll ett kort eget provsvar. Listan visar vad som ryms; den lovar inte full täckning.</p>':''}${a.mode==='extra'?'<p class="fine">Extra: utveckla svar med alternativa förklaringar, försök och modellbegränsningar. Välj särskilt frågorna Resistensen stannar kvar, Membranets regler byter villkor och Testa en förklaring om konservering.</p>':''}</section><div class="section-top"><h2>Huvudschemat · standardprogram</h2></div><div class="tabs" aria-label="Välj studiedag"><button data-action="day" data-day="1" aria-pressed="${day===1}">Dag 1 · måndag</button><button data-action="day" data-day="2" aria-pressed="${day===2}">Dag 2 · tisdag</button></div><div class="info-strip">${icon('clock')} ${day===1?'Hemma cirka 14:20. Ät och landa först. Dela 75-minutersfönstren i kortare fokusblock och ta 10 minuters paus inom varje fönster.':'Hemma cirka 13:40–14:00. Ät före start. Fotboll 16:30–19:00. Om kvällen börjar 21:00: välj 25 effektiva minuter, exempelvis 10 min egna svar + 15 min luckor, och sluta 21:30.'}</div><div class="session-list">${C.sessions.filter(s=>s.day===day).map(s=>{const done=s.tasks.every(t=>state.tasks[t[0]]);return `<article class="card session-card ${done?'done':''}"><div class="session-time">${s.time}<small>${s.effective} min fokus<br>${s.pause} min pauser</small></div><div><span class="eyebrow">PASS ${s.id}</span><h3>${s.title}</h3><p>${s.goal}</p><p class="fine">Kontroll: ${s.check}</p></div><div class="actions">${done?'<span class="check-circle">✓</span>':''}${button('Öppna passet','session/'+s.id,'secondary small')}</div></article>`}).join('')}</div><section class="card space-top"><h3>Om du blir trött eller hamnar efter</h3><p>Sänk återstående tid i inställningarna. Börja med en tvåminutersstart: öppna en fråga och säg vad du vet. Låt sedan ett 15-minutersblock räcka för en mekanism. När du redan kan: gör kärnfrågorna direkt och gå vidare när du själv kan motivera svaren utan stöd.</p><p>På tisdag kväll: återkalla först, läs bara för att reparera ett konkret fel och försök sedan igen utan stöd. Flytta inte stora delar av nyinlärningen till en sen kväll.</p></section>`;}
function sessionPage(id){const s=C.sessions.find(x=>x.id===+id);if(!s)return missing();return `${back('Studieplan','plan')}${title('DAG '+s.day+' · PASS '+s.id,s.title,`${s.time} · ${s.effective} effektiva minuter + ${s.pause} minuters pauser.`)}<div class="two-cols"><section class="card"><h3>Det här ska du kunna efteråt</h3><p>${s.goal}</p><h3>Varför just nu?</h3><p>${s.why}</p><h3>Gör i den här ordningen</h3><ul class="task-list">${s.tasks.map(([id,label,min,path])=>`<li><input type="checkbox" id="task-${id}" data-task="${id}" ${state.tasks[id]?'checked':''}><label for="task-${id}"><a href="#${path}">${label}</a><small>${min} min · markerar genomförd aktivitet, inte säker kunskap</small></label>${button('Börja',path,'secondary small')}</li>`).join('')}</ul><div class="actions"><button class="button" data-action="focus">${icon('clock')} Starta ${state.focusLength} min fokus</button>${button(s.id===6?'Till repetition':'Till nästa pass',s.id===6?'review':'session/'+(s.id+1),'secondary')}</div></section><aside><section class="card"><span class="pill must">OBLIGATORISKT</span><h3 class="space-top">Lär → återkalla → kontrollera</h3><p>${s.check}</p><hr><span class="pill extra">KAN HOPPAS ÖVER</span><p class="space-top">${s.skip}</p></section><div class="info-strip space-top">${icon('leaf')}<span>${s.next}</span></div></aside></div>`;}
function course(){return `${title('SJU OMRÅDEN · INGET ANNAT','Lär mekanismen. Testa direkt.','Varje område har sex steg, fyra kärnfrågor och tydligt avgränsad fördjupning. Riktmärkena är ämnesandelar; de är inga extra pass utöver schemat.')}<div class="filter-row"><label for="course-search">Hitta område eller begrepp</label><input id="course-search" type="search" placeholder="Till exempel ribosom eller turgor" value="${esc(courseFilter)}" style="border:1px solid var(--line);border-radius:9px;padding:10px 14px;width:320px"></div><div class="topic-grid" id="topic-results">${filteredChapters()}</div><div class="info-strip space-top">${icon('check')}Kan du redan ett område? Öppna ”Testa direkt” i kapitlet. En säker markering bygger på att du kan förklara själv, utan facit.</div>`;}
function filteredChapters(){const q=courseFilter.toLocaleLowerCase('sv');const list=C.chapters.filter(c=>[c.title,...c.terms].join(' ').toLocaleLowerCase('sv').includes(q));return list.map(topicCard).join('')||'<p class="muted">Inget område matchar. Prova ett annat begrepp.</p>';}
function osmosisLab(){return `<section class="lab" aria-labelledby="osmos-lab-title"><span class="eyebrow">VISUELL FÖRKLARING</span><h3 id="osmos-lab-title">Förutsäg innan du drar.</h3><p>Vart går vattnet? Ändra halten utanför och jämför celltyperna. Modellen antar vattenpermeabla membran och ämnen som inte passerar under den visade tiden.</p><label for="osm-range">Effektiv partikelhalt utanför · <output id="osm-value">300</output> mOsm/L</label><input id="osm-range" type="range" min="100" max="600" step="25" value="300"><div class="lab-presets"><button data-action="osm-preset" data-value="150">Hypoton</button><button data-action="osm-preset" data-value="300">Isoton referens</button><button data-action="osm-preset" data-value="500">Hyperton</button></div><div class="lab-art"><div class="lab-cell"><svg viewBox="0 0 220 170" role="img" aria-label="Förenklad blodkropp, volymen ändras med omgivningens halt"><ellipse id="rbc" cx="110" cy="86" rx="43" ry="35" fill="#d2a28e" stroke="#a77866" stroke-width="2"/><ellipse id="rbc-center" cx="110" cy="86" rx="21" ry="15" fill="#e6c5b7"/><text id="rbc-flow" x="110" y="155" text-anchor="middle" font-size="13" fill="#4b6850">Vatten ⇄</text></svg><strong>Röd blodkropp</strong></div><div class="lab-cell"><svg viewBox="0 0 220 170" role="img" aria-label="Förenklad växtcell med stel vägg, membran och vakuol"><rect x="43" y="27" width="134" height="111" rx="18" fill="none" stroke="#758b4e" stroke-width="7"/><rect id="plant-membrane" x="49" y="33" width="122" height="99" rx="14" fill="#dbe8bc" stroke="#718b53" stroke-width="2"/><rect id="vacuole" x="66" y="48" width="88" height="69" rx="18" fill="#b6cf9a"/><text id="plant-flow" x="110" y="155" text-anchor="middle" font-size="13" fill="#4b6850">Vatten ⇄</text></svg><strong>Växtcell</strong></div></div><div class="lab-result" id="osm-result" aria-live="polite"></div><p class="fine" style="margin:12px 0 0">Referensen är 300 mOsm/L inne före förändringen. Storlek och gränser är schematiska; detta är ingen kvantitativ cell- eller medicinsk simulering.</p></section>`;}
const pumpSteps=[['Bind på insidan','Tre Na⁺ binder till pumpens inåtvända bindningsställen.','3 Na⁺ →'],['Använd ATP','ATP hydrolyseras. Pumpen fosforyleras och ändrar form.','ATP → ADP + Pᵢ'],['Släpp ut Na⁺','Den utåtvända formen avger tre Na⁺ till utsidan.','3 Na⁺ ut'],['Bind på utsidan','Två K⁺ binder till den utåtvända pumpen.','← 2 K⁺'],['Återställ formen','Fosfat avges och pumpen återgår till inåtvänd form.','Pᵢ avges'],['Släpp in K⁺','Två K⁺ avges inne. Ett varv: 3 Na⁺ ut, 2 K⁺ in, 1 ATP.','2 K⁺ in']];let pumpPos=0;
function pumpLab(){const p=pumpSteps[pumpPos];return `<section class="lab" aria-labelledby="pump-title"><span class="eyebrow">STEG FÖR STEG</span><h3 id="pump-title">Säg nästa steg innan du klickar.</h3><div class="pump-dots">${pumpSteps.map((x,i)=>`<i class="${i<=pumpPos?'on':''}"></i>`).join('')}</div><div class="pump-stage"><div class="pump-art"><div class="pump-core" style="transform:rotate(${pumpPos>1&&pumpPos<5?7:0}deg)">${p[2]}</div></div><div aria-live="polite"><small class="fine">${pumpPos+1} / 6 · Na⁺/K⁺-pumpen</small><h4>${p[0]}</h4><p>${p[1]}</p></div></div><div class="actions"><button class="button secondary small" data-action="pump-prev" ${pumpPos===0?'disabled':''}>← Förra</button><button class="button small" data-action="pump-next">${pumpPos===5?'Börja om':'Nästa steg →'}</button></div><p class="fine space-top">Formändringen visas schematiskt. Pumpen arbetar mot jongradienter och är skild från en öppen jonkanal.</p></section>`;}
function chapterPage(id){const c=chapter(id);if(!c)return missing();const own=C.cards.filter(x=>x.chapter===id);const limited=E.remain(state)<=200;return `${back('Alla sju områden','course')}${title(c.n+' · '+c.source,c.title,c.why)}<div class="actions">${pill()}<span class="fine">Riktmärke ${c.minutes} min inklusive återkallning</span><a class="button secondary small" href="#chapter/${id}/test">Testa direkt →</a></div><div class="teaching-layout space-top"><article><section aria-label="Undervisning i sex steg">${c.steps.map((s,i)=>`<section class="lesson-step" id="step-${i+1}"><span class="step-number">${i+1}</span><div><h2>${s[0]}</h2>${s.slice(1).map(p=>`<p>${p}</p>`).join('')}</div></section>`).join('')}</section>${id==='osmos'?osmosisLab():id==='aktiv'?`<div id="pump-lab">${pumpLab()}</div>`:''}<div class="misconception"><h3>Vanliga provfällor</h3><ul>${c.traps.map(x=>`<li>${x}</li>`).join('')}</ul></div><details class="details-block"><summary>${pill('deep')} Fördjupa modellen när kärnan sitter</summary>${limited?'<p class="fine">Du har valt en kort tidsbudget. Öppna detta först om kärnfrågorna redan känns säkra.</p>':''}${c.deeper.map(([h,p])=>`<h3>${h}</h3><p>${p}</p>`).join('')}</details><details class="details-block"><summary>${pill('extra')} Extra från boken och lektionen</summary>${c.extra.map(([h,p])=>`<h3>${h}</h3><p>${p}</p>`).join('')}</details><section id="chapter-questions"><div class="section-top"><h2>Förklara utan stöd.</h2><span class="fine">4 kärnfrågor</span></div><p class="fine">Skriv en kort förklaring, säg den högt eller markera ärligt att du inte kan ännu. Visa sedan svaret och självskatta.</p>${own.map(cardHTML).join('')}</section><div class="actions">${button('Träna ett öppet provsvar','exams/'+id)}${button('Repetera svagaste frågorna','review','secondary')}</div></article><aside class="lesson-index"><nav aria-label="Kapitlets steg">${c.steps.map((s,i)=>`<a href="#chapter/${id}/step-${i+1}" data-scroll="step-${i+1}">${i+1}. ${s[0]}</a>`).join('')}<a href="#chapter/${id}/test">→ Kontrollera förståelsen</a></nav><section class="card space-top"><h3>Ord att använda precist</h3><div class="term-cloud">${c.terms.map(t=>`<span>${t}</span>`).join('')}</div><p>Förklara vad orden gör i processen. En lista med begrepp ersätter inte en mekanism.</p></section><section class="card space-top"><h3>Relevant provträning</h3>${C.exams.filter(e=>e.chapters.includes(id)).slice(0,3).map(e=>`<a class="back" style="margin:8px 0" href="#exam/${e.id}">${e.title} →</a>`).join('')}</section></aside></div>`;}
const preparedResponses=new Set(),supportViewed=new Set(),activeAttempts=new Set();
function prepareResponse(id){
  if(preparedResponses.has(id))return;
  const a=state.attempts[id];
  if(a&&state.drafts[id]===a.text){state.drafts[id]='';save();}
  else if(!a&&(state.cards[id]||state.exams[id])&&state.drafts[id]){
    const q=E.assessments(C).find(x=>x.id===id),n=C.rubrics[id]?.length||q?.points.length;
    state.attempts[id]={text:state.drafts[id],spoken:false,assisted:false,at:0,checks:Array(n).fill(false),graded:true};state.drafts[id]='';save();
  }
  preparedResponses.add(id);
}
function responseInput(id,label,reveal){
  const a=state.attempts[id],locked=activeAttempts.has(id);return `<label class="answer-label" for="response-${id}">${label}</label><textarea id="response-${id}" data-draft="${id}" maxlength="40000" ${locked?'readonly':''} placeholder="Förklara ur minnet: vad händer, varför och med vilken följd?">${esc(locked?a?.text||'':state.drafts[id]||'')}</textarea><label class="fine oral-choice"><input type="checkbox" data-spoken="${id}" ${spoken.has(id)||reveal&&a?.spoken?'checked':''} ${locked?'disabled':''}> Jag har formulerat ett svar högt eller på papper</label><p class="fine" data-attempt-hint="${id}">${locked?'Försöket före facit är låst för jämförelsen. Ett nytt försök får ett tomt fält.':'Ett tidigare svar visas inte automatiskt som stöd i det nya försöket.'}</p>${locked&&!reveal?`<button class="button secondary small" data-action="fresh-response" data-id="${id}">Nytt försök utan stöd</button>`:''}${!locked&&a?.text?`<details class="details-block previous-response" data-previous="${id}"><summary>Visa föregående svar som stöd</summary><p>${esc(a.text)}</p><p class="fine">Öppnar du detta räknas försöket som stöttat. Välj ett nytt tomt försök för att testa utan stöd.</p></details>`:''}`;
}
function captureResponse(id,assisted=false){
  if(activeAttempts.has(id)){if(assisted){state.attempts[id].assisted=true;state.attempts[id].checks.fill(false);}shown.add(id);save();return true;}
  const text=(state.drafts[id]||'').trim();if(!assisted&&!text&&!spoken.has(id)){toast('Försök först själv, eller välj stödet om du inte vet ännu.');return false;}
  E.startAttempt(state,C,id,state.drafts[id]||'',spoken.has(id),assisted||supportViewed.has(id));activeAttempts.add(id);shown.add(id);save();return true;
}
function reasoningHTML(){return `<details class="details-block"><summary>Stresstesta resonemanget · cirka 30 sekunder</summary><ul class="reasoning-list">${C.reasoningChecks.map(x=>`<li>${x}</li>`).join('')}</ul><p class="fine">Detta är frågor för självkontroll. Checklistan är ingen automatisk textanalys eller officiell betygsmatris.</p></details>`;}
function assessmentHTML(q,showTitle=true){
  prepareResponse(q.id);const reveal=shown.has(q.id),a=state.attempts[q.id],saved=state.exams[q.id]||state.practice[q.id],checks=a?.checks||q.points.map(()=>false);
  const related=C.variations.filter(x=>x.parents?.includes(q.id));
  return `<section class="question-card assessment-card" data-assessment="${q.id}">${showTitle?`<h3>${q.title}</h3>`:''}<p class="assessment-prompt">${q.q}</p>${responseInput(q.id,'Ditt eget svar · '+q.title,reveal)}<div class="actions"><button class="button" data-action="show-assessment" data-id="${q.id}">${reveal?'Stäng modellsvar och bedömningspunkter':'Visa modellsvar och bedömningspunkter'}</button><button class="quiet fine" data-action="support-assessment" data-id="${q.id}">Jag kommer inte igång – visa stöd</button></div><div class="assessment-feedback" ${reveal?'':'hidden'}><div class="answer-model"><span class="eyebrow">ETT MÖJLIGT BIOLOGISKT RESONEMANG</span><p>${q.model}</p></div>${q.develop?`<div class="feedback-section"><h4>Från ytligt till utvecklat</h4><p>${q.develop}</p></div>`:''}${q.terms?`<div class="term-cloud">${q.terms.map(x=>`<span>${x}</span>`).join('')}</div>`:''}${q.mistake||q.trap?`<div class="misconception"><h4>Vanligt misstag</h4><p>${q.mistake||q.trap}</p></div>`:''}<h4>Vilka poänger förklarade du före facit?</h4><p class="fine">Tomma rutor blir konkreta luckor i repetitionen. Bedöm betydelsen, inte identiska formuleringar.</p><div class="self-check">${q.points.map((p,i)=>`<label><input type="checkbox" data-assessment-check="${q.id}" data-index="${i}" ${checks[i]?'checked':''} ${a?.assisted?'disabled':''}><span>${p[1]}</span></label>`).join('')}</div>${a?.assisted?'<p class="fine">Du öppnade stödet före ett självständigt försök. Spara luckorna och gör därefter ett nytt försök utan stöd.</p>':''}<div class="actions"><button class="button" data-action="save-assessment" data-id="${q.id}">Spara min självbedömning</button><button class="button secondary" data-action="fresh-response" data-id="${q.id}">Nytt försök utan stöd</button></div><p class="fine space-top" data-assessment-result="${q.id}">${saved?'Senast sparat: '+saved.checks.filter(Boolean).length+'/'+q.points.length+' centrala poänger. Nya markeringar sparas med knappen.':''}</p>${reasoningHTML()}${related.length?`<div class="feedback-section"><h4>Kan du samma mekanism när villkoret ändras?</h4>${related.map(x=>button(x.title,'variation/'+x.id,'secondary small')).join('')}</div>`:''}<p class="fine">Dölj modellen och förklara den viktigaste saknade länken igen. Sparade poänger är självbedömning och kan inte räknas om till ett A.</p></div></section>`;
}
function variationPage(id){const q=C.variations.find(x=>x.id===id);if(!q)return missing();return `${back('Provträningen','exams')}${title('ÄNDRAT VILLKOR · 4 MINUTER INKLUSIVE JÄMFÖRELSE',q.title,'2 minuter eget svar, 1 minut jämförelse och 1 minut för att reparera den viktigaste länken med modellen stängd.')}<div class="reading-width">${assessmentHTML(q,false)}</div>`;}
function variationsList(){return `<section class="space-top"><h2>Fyra ändrade situationer</h2><p class="fine">En variation i pass 2, 3, 4 och 5. De ersätter annan aktivitet i passet och tillför ingen extra studietid.</p><div class="topic-grid">${C.variations.map((q,i)=>`<a class="topic-link" href="#variation/${q.id}"><span class="topic-number">${i+1}</span><div><h3>${q.title}</h3><p>4 min · tillämpa och bedöm själv</p></div>${icon('arrow')}</a>`).join('')}</div><div class="actions space-top">${button('Avslutande kontroll · 5 min','exit-check','secondary')}</div></section>`;}
function exitPage(){return `${back('Studiepass 6','session/6')}${title('AVSLUTANDE KONTROLL · 5 EFFEKTIVA MINUTER','Tre nya situationer. Utan stöd.','Skriv ungefär en minut per situation. Använd två minuter till jämförelse och markera vad som saknades. Detta är en luckkontroll, ingen betygsprognos.')}<div class="reading-width">${C.exit.map(q=>assessmentHTML(q,true)).join('')}</div><section class="card"><h3>Välj den viktigaste kvarvarande luckan</h3><p class="fine">Alla svar behöver inte vara perfekta. Kan du inte förklara en mekanism, återkom till den inom din kvarvarande tid. Om tiden är slut: avsluta och skydda återhämtningen.</p>${button('Se exakta luckor','progress','secondary')}</section>`;}
function gapListHTML(){const gaps=E.gaps(state,C);if(!gaps.length)return '';return `<section class="card space-top"><h3>Det här saknades i dina egna svar</h3><p class="fine">Dessa poänger kommer från din självbedömning. Förklara en saknad länk utan stöd, kontrollera och spara ett nytt försök.</p><ul class="gap-list">${gaps.slice(0,6).map(g=>{const path=g.kind==='card'?'chapter/'+g.chapter+'/question-'+g.id:g.kind==='exam'?'exam/'+g.id:g.id.startsWith('f')?'exit-check':'variation/'+g.id;return `<li><span>${g.text}</span><a href="#${path}">Försök igen →</a></li>`}).join('')}</ul>${gaps.length>6?`<p class="fine">${gaps.length-6} ytterligare poänger påverkar prioriteringen. Börja med en mekanism åt gången.</p>`:''}</section>`;}
function refreshResponse(id){if(C.cards.some(x=>x.id===id))repaintCard(id);else {const q=E.assessments(C).find(x=>x.id===id),el=document.querySelector(`[data-assessment="${id}"]`);if(q&&el)el.outerHTML=assessmentHTML(q,route==='exit-check');}}
function freshResponse(id){activeAttempts.delete(id);state.drafts[id]='';shown.delete(id);spoken.delete(id);supportViewed.delete(id);preparedResponses.add(id);save();refreshResponse(id);document.querySelector(`[data-draft="${id}"]`)?.focus();toast('Nytt tomt försök. Förklara med modellen stängd.');}
function cardHTML(c,compact=false){
  prepareResponse(c.id);const r=state.cards[c.id],reveal=shown.has(c.id),a=state.attempts[c.id],checks=a?.checks||[];
  return `<section class="question-card" id="question-${c.id}" data-card="${c.id}"><div class="question-top"><span>${chapter(c.chapter).title} · ${c.type}</span><span>${r?'Senast: '+['Inte kan','Delvis kan','Kan säkert'][r.rating]:'Inte bedömd'}</span></div><h3>${c.q}</h3>${responseInput(c.id,'Din förklaring ur minnet',reveal)}<div class="actions"><button class="button secondary small" data-action="show-card" data-id="${c.id}">${reveal?'Dölj biologiska poänger':'Visa biologiska poänger'}</button><button class="quiet fine" data-action="unknown-card" data-id="${c.id}">Jag vet inte ännu</button></div><div ${reveal?'':'hidden'}><div class="answer-model"><span class="eyebrow">JÄMFÖR MED DITT FÖRSÖK FÖRE FACIT</span><p>${c.a}</p></div><h4>Vilka poänger fanns i din förklaring?</h4><p class="fine">Markera det du förklarade före facit. Svarstexten rättas inte automatiskt.</p><div class="self-check core-check">${C.rubrics[c.id].map((p,i)=>`<label><input type="checkbox" data-core-check="${c.id}" data-index="${i}" ${checks[i]?'checked':''} ${a?.assisted?'disabled':''}><span>${p}</span></label>`).join('')}</div>${a?.assisted?'<p class="fine">Du använde stöd före försöket. Poängerna är därför inte visade självständigt ännu. Stäng stödet och gör ett nytt försök.</p>':''}<div class="confidence" aria-label="Självskatta frågan">${[0,1,2].map((v,i)=>`<button data-action="rate" data-id="${c.id}" data-rating="${v}" aria-pressed="${r?.rating===v}" ${v===2&&(!checks.every(Boolean)||checks.length!==3||a?.assisted)?'disabled':''}>${['Inte kan','Delvis kan','Kan säkert'][i]}</button>`).join('')}</div><p class="fine space-top">${r?.retainedAt?'Självskattad återkallning efter paus registrerad.':r?.rating===2?'Säker direkt efter försöket. Testa igen efter minst 10 minuter innan du litar på minnet.':'Kan säkert blir valbart när alla tre poänger fanns i ditt eget försök utan stöd.'}</p><button class="button secondary small" data-action="fresh-response" data-id="${c.id}">Nytt försök utan stöd</button></div></section>`;
}
function diagnostic(){const ids=['c1','m2','o1','a2','b1','r2','v2'];const c=C.cards.find(x=>x.id===ids[diagnosticPos]);return `${title('SNABBDIAGNOS · UTAN FACIT FÖRST','Börja där du är.','Försök cirka en minut per fråga. ”Inte kan” är användbar information. Självskattningen hjälper planen att prioritera.')}<div class="progress-track" role="progressbar" aria-label="Frågor i snabbdiagnosen" aria-valuemin="0" aria-valuemax="7" aria-valuenow="${diagnosticPos}"><span style="width:${diagnosticPos/7*100}%"></span></div><p class="fine space-top">Fråga ${diagnosticPos+1} av 7</p><div class="reading-width">${cardHTML(c,true)}<div class="actions"><button class="button secondary" data-action="diag-back" ${diagnosticPos===0?'disabled':''}>← Förra</button><button class="button" data-action="diag-next">${diagnosticPos===6?'Spara diagnosen och fortsätt':'Nästa område →'}</button></div></div>`;}
function reviewPage(){if(!review){const list=E.dueCards(state,C,reviewFilter,reviewChapter);review={ids:list.map(x=>x.id).slice(0,8),pos:0};}const c=C.cards.find(x=>x.id===review.ids[review.pos]);const missed=C.exams.filter(e=>{const a=state.exams[e.id];return a&&a.checks.some(v=>!v)});return `${title('ÅTERKALLA · JÄMFÖR · FÖRSÖK IGEN','Repetera där det gör skillnad.','Högst åtta frågor per varv. Okända och osäkra frågor, förfallna repetitioner och områden med missade provpoänger prioriteras.')}<div class="filter-row"><label for="review-filter">Visa</label><select id="review-filter"><option value="weak" ${reviewFilter==='weak'?'selected':''}>Mina luckor och dagens repetition</option><option value="due" ${reviewFilter==='due'?'selected':''}>Bara förfallna repetitioner</option><option value="unseen" ${reviewFilter==='unseen'?'selected':''}>Bara oprövade frågor</option><option value="all" ${reviewFilter==='all'?'selected':''}>Alla kärnfrågor</option></select><label for="review-chapter">Område</label><select id="review-chapter"><option value="">Alla sju områden</option>${C.chapters.map(x=>`<option value="${x.id}" ${reviewChapter===x.id?'selected':''}>${x.title}</option>`).join('')}</select></div>${c?`<p class="fine">Fråga ${review.pos+1} av ${review.ids.length} i det här varvet · försök först utan stöd</p><div class="reading-width">${cardHTML(c,true)}<div class="actions"><button class="button secondary" data-action="review-prev" ${review.pos===0?'disabled':''}>← Förra</button><button class="button" data-action="review-next">${review.pos===review.ids.length-1?'Avsluta varvet':'Nästa fråga →'}</button></div></div>`:`<div class="empty"><h2>${review.ids.length?'Varvet är klart.':'Inga frågor i det valda urvalet.'}</h2><p>${review.ids.length?'Ta en paus och återkom. Använd sedan kunskapen i en öppen fråga.':'Om en repetition inte är förfallen ännu kan du välja alla kärnfrågor eller skriva ett eget provsvar.'}</p><div class="actions" style="justify-content:center"><button class="button secondary" data-action="review-new">Nytt varv</button>${button('Till provträningen','exams')}</div></div>`}${gapListHTML()}${missed.length?`<section class="card space-top"><h3>Gå tillbaka till missade provpoänger</h3><p>En kärnfråga kan vara säker samtidigt som en tillämpning behöver mer träning. Försök svara igen före facit.</p>${missed.map(e=>`<a class="back" style="margin:7px 12px 7px 0" href="#exam/${e.id}">${e.title} →</a>`).join('')}</section>`:''}<p class="fine space-top">Inte kan återkommer efter cirka 10 minuter, Delvis kan efter 4 timmar. Första Kan säkert återkommer efter 10 minuter. Först efter en ny säker återkallning med minst 10 minuters mellanrum föreslås 18 timmar. Alla nivåer är självskattade.</p>`;}
function examsPage(filter=''){if(filter)examFilter=filter;const list=C.exams.filter(e=>!examFilter||e.chapters.includes(examFilter));return `${title('PROVTRÄNING – SIKTA MOT A','Skriv själv. Utveckla sedan.','Öppna scenarier med flera möjliga resonemang. Standardprogrammet väljer frågorna 2, 4, 13 och 3 samt fyra korta variationer. Övriga frågor finns kvar som valbart material inom din tidsbudget. Modellsvaren visar möjliga svar; checklistan är ingen officiell betygsgräns.')}<div class="info-strip">${icon('pen')}Använd kedjan: påstående → mekanism → konsekvens → relevant villkor. Precision och välgrundade samband väger mer än fler ord.</div><div class="filter-row"><label for="exam-chapter">Filtrera område</label><select id="exam-chapter"><option value="">Alla sju områden</option>${C.chapters.map(x=>`<option value="${x.id}" ${examFilter===x.id?'selected':''}>${x.title}</option>`).join('')}</select></div><div class="exam-list">${list.map(e=>{const a=state.exams[e.id];return `<article class="card"><div class="question-top"><span>FRÅGA ${C.exams.indexOf(e)+1} · ${e.minutes} MIN SKRIVTID</span><span>${a?a.checks.filter(Boolean).length+'/'+e.points.length+' poänger med':'Eget svar först'}</span></div><h2>${e.title}</h2><p>${e.q}</p><div class="term-cloud">${e.chapters.map(x=>`<span>${chapter(x).title}</span>`).join('')}</div>${button(a?'Träna igen':'Öppna frågan','exam/'+e.id,'secondary small')}</article>`}).join('')}</div>${variationsList()}`;}
function examPage(id){
  const e=C.exams.find(x=>x.id===id);if(!e)return missing();
  return `${back('Alla öppna provfrågor','exams')}${title('PROVTRÄNING – SIKTA MOT A · '+e.minutes+' MIN SKRIVTID',e.title,'Skriv först utan stöd. Jämför sedan med poängerna, välj din viktigaste lucka och försök igen med modellen stängd. Standardpassets tid inkluderar självbedömningen.')}<div class="exam-grid"><section>${assessmentHTML(e,false)}</section><aside class="card"><span class="eyebrow">EN KEDJA ATT FÖRKLARA</span><h3>Orsak → mekanism → konsekvens</h3><p>Vilket villkor behöver du ange? Vad skulle ändras om det villkoret byttes?</p><p class="fine">Kontrollera vad du faktiskt skrev före facit. Ett annat korrekt resonemang kan uppfylla samma poäng.</p>${e.chapters.map(x=>`<a class="back" href="#chapter/${x}">${chapter(x).title} →</a>`).join('')}</aside></div>`;
}
function connectionsPage(id){const list=id?C.connections.filter(x=>x.id===id):C.connections;return `${id?back('Alla biologiska samband','connections'):''}${title('BIOLOGISKA SAMBAND – FÖRSTÅ HELHETEN','Samma mekanism. Fler möjliga svar.','Säg kedjan själv, kontrollera varje pil och prova den sedan i en öppen fråga. Koppla bara sådant som hjälper dig förklara det som efterfrågas.')}<div class="connection-grid">${list.map(s=>`<article class="card connection-card"><div class="term-cloud">${s.chapters.map(x=>`<span>${chapter(x).title}</span>`).join('')}</div><h2>${s.title}</h2><div class="chain">${s.chain.map((v,i)=>`${i?'<b aria-hidden="true">→</b>':''}<span>${v}</span>`).join('')}</div><p><strong>Varför sambandet spelar roll:</strong> ${s.why}</p><p><strong>I ett provsvar:</strong> ${s.use}</p><details class="details-block"><summary>Jämför ett enkelt och ett utvecklat resonemang</summary><div class="comparison"><div><small>ENKEL START</small><p>${s.basic}</p></div><div><small>UTVECKLAD ORSAKSKEDJA</small><p>${s.advanced}</p></div></div><div class="term-cloud">${s.terms.map(t=>`<span>${t}</span>`).join('')}</div></details>${button('Använd sambandet i en provfråga','exam/'+s.exam,'secondary small')}</article>`).join('')}</div>`;}
function progress(){const stats=C.chapters.map(c=>({c,s:E.chapterStats(state,C,c.id)}));return `${title('DINA KUNSKAPSLUCKOR','Visa det du kan förklara.','Läsning och genomförda uppgifter är aktiviteter. Kärnfrågorna och dina egna svar ger en mer användbar bild av vad du behöver återkomma till. All kunskapsnivå här är självskattad.')} ${statsHTML()}${gapListHTML()}<div class="weak-list">${stats.map(({c,s})=>`<article class="weak-row"><span class="topic-number">${c.n}</span><div><h3>${c.title}</h3><p>${s.unknown} oprövade · ${s.total-s.secure-s.unknown} osäkra · ${s.missed} saknade biologiska poänger</p><div class="progress-track"><span style="width:${s.secure/s.total*100}%"></span></div></div><strong>${s.secure}<small class="fine"> / ${s.total}</small></strong><a class="button secondary small" href="#review/${c.id}">Repetera →</a></article>`).join('')}</div><section class="card"><h3>Hur repetitionen prioriteras</h3><p>Oprövade och osäkra frågor kommer före redan säkra. En missad provpoäng gör området mer angeläget, även om kärnfrågorna känns lätta. Säkra frågor kommer tillbaka efter tid. En trygg markering efter att du precis sett facit är svagare underlag än en förklaring som fungerar efter en paus.</p><p class="fine">Inga sökord eller språkmodeller betygsätter ditt svar. Checklistan gör bedömningen synlig. ”Trygg” betyder din egen säkerhet, inte verifierad behärskning.</p></section>`;}
function sources(){return `${title('TRANSPARENS & KVALITET','Byggd på ditt material. Granskad för förståelse.','Kursen omfattar enbart de sju angivna områdena. Öppna frågor är en rimlig träningsinriktning utifrån din uppgift, inte verifierad information om lärarens prov.')}<section class="card"><h3>Så valdes innehållet</h3><p>Prioriteten bygger på fyra bedömningar: centralitet, användbarhet i flera frågor, betydelse som förkunskap och rimlig inlärningstid. Gradienter och membrantransport får stor vikt eftersom de förklarar många nya situationer. Cellens baskunskaper och alla sju områden behålls. Uppskattade minuter är riktmärken, inte uppmätta individuella inlärningstider.</p><div class="table-wrap"><table><thead><tr><th>Aktivitet i standardprogrammet</th><th>Effektiv tid</th></tr></thead><tbody>${C.timeBudget.map(([label,min])=>`<tr><td>${label}</td><td>${min} min</td></tr>`).join('')}<tr><td><strong>Totalt</strong></td><td><strong>360 min</strong></td></tr></tbody></table></div><p class="fine">Varje minut räknas en gång i huvudschemat. Tiderna inkluderar jämförelse med facit och nya försök. Pauser tillkommer inom de angivna klockslagsfönstren. Uppskattningen är inte en uppmätt genomförandetid för varje elev. Alla 13 provfrågor är tillgängliga, men standardprogrammet väljer fyra av dem; övriga är extra. Fyra variationer och den avslutande kontrollen ingår i de 360 minuterna.</p></section><section class="card space-top"><h3>Vad som faktiskt granskades i originalet</h3><p>Källfilens inbäddade HTML-sidor för celler, membran, osmos, aktiv transport, mikrober, antibiotika och växtcell: rubriker, faktatexter, ordlistor, flashcards, quiz och deras förklaringar, diagrammens etiketter och interaktionernas kod. Dessa beskriver bok, filmer och PPT. Originalens PowerPoint-filer, hela filmer och ursprungliga bokfoton var inte separat tillgängliga som kompletta primärkällor här; täckningen bygger på vad Biologiatlas återger.</p><p>Överlappande flashcards har sammanförts till 28 kärnfrågor. Långa listor, gamla statistiktal och detaljmått ligger efter mekanismerna. Alla obligatoriska aktiviteter är kopplade till de sju områdena.</p></section><section class="card space-top"><h3>Viktiga preciseringar jämfört med originalet</h3><ul style="font-size:14px"><li>Osmolalitet mäts per kg lösningsmedel. Tonicitet beror på membranets permeabilitet, och tryck kan motverka osmos.</li><li>En växtcell i isoton miljö är relativt slapp; hög turgor kräver en lämplig vattenpotentialskillnad och väggens motstånd.</li><li>Kanaler driver inte riktat flöde. Pumpar har energibegränsningar; jontransport påverkas av elektrisk spänning.</li><li>Plasmider kan ha stabiliserande system. Resistens försvinner inte säkert när antibiotika tas bort.</li><li>Antibiotikans effekt kan vara tillväxthämmande. Råd om dos och behandlingstid är att följa ordination, inte att generellt ta högre dos eller längre kur.</li><li>Herpeslatens är inte samma sak som fagers lysogeni. Virusinträde kan ske på olika sätt.</li><li>Växtceller har mitokondrier och alla har inte kloroplaster. Spektrin hör till cellens inre stöd, inte ECM.</li><li>Originalets gamla art-, biomassa-, malaria- och bakterieantal används inte som provsanningar eller aktuella fakta. Äldre protistindelning märks som traditionell.</li></ul></section><section class="card space-top"><h3>Vad betyder ”sikta mot A” här?</h3><p>Att träna precis begreppsanvändning, förklarade orsakssamband, tillämpning i nya situationer och relevanta villkor. En modelltext är ett exempel, ingen garanti för en viss provpoäng eller ett kursbetyg. Läraren bedömer uppgiftens krav och elevens samlade kunskaper. Planen kan hjälpa dig utnyttja sex timmar väl men lovar inte att ersätta en hel kurs.</p></section><div class="section-top"><h2>Källor och kontrollunderlag</h2></div><div class="source-list">${C.sources.map(([h,u,p])=>`<article class="card"><a href="${u}" target="_blank" rel="noopener noreferrer">${h} ↗</a><p>${p}</p></article>`).join('')}</div><p class="fine space-top">Material och kod sammanställda för 2–3 november 2026. Innehållet är omformulerat och nya frågor är skapade för den här kursen. Ingen del av Biologiatlas har skrivits över.</p>`;}
function missing(){return `${title('SIDAN FINNS INTE','Välj nästa steg.','Den här länken kunde inte hittas i kursen.')} ${button('Till överblicken','home')}`;}
function render(){const raw=decodeURIComponent(location.hash.slice(1)||'home');const parts=raw.split('/');const old=route;route=raw;if(parts[0]!=='review')review=null;if(parts[0]==='review'&&parts[1]&&reviewChapter!==parts[1]){reviewChapter=chapter(parts[1])?parts[1]:'';review=null;}
  let html,crumb;switch(parts[0]){case'home':html=home();crumb='Din överblick';break;case'plan':html=plan();crumb='Din studieplan';break;case'session':html=sessionPage(parts[1]);crumb='Studieplan / Pass '+parts[1];break;case'course':html=course();crumb='De sju områdena';break;case'chapter':html=chapterPage(parts[1]);crumb='Kursen / '+(chapter(parts[1])?.title||'Område');break;case'diagnostic':html=diagnostic();crumb='Snabbdiagnos';break;case'review':html=reviewPage();crumb='Fokuserad repetition';break;case'exams':html=examsPage(parts[1]);crumb='Provträning – sikta mot A';break;case'exam':html=examPage(parts[1]);crumb='Provträning / Eget svar';break;case'variation':html=variationPage(parts[1]);crumb='Provträning / Ändrat villkor';break;case'exit-check':html=exitPage();crumb='Avslutande kunskapskontroll';break;case'connections':html=connectionsPage();crumb='Biologiska samband';break;case'connection':html=connectionsPage(parts[1]);crumb='Biologiskt samband';break;case'progress':html=progress();crumb='Dina kunskapsluckor';break;case'sources':html=sources();crumb='Källor & avgränsning';break;default:html=missing();crumb='Kursen';}
  $('#main').innerHTML=html;$('#breadcrumb').textContent=crumb;document.title=crumb+' · Biologi 2';renderNav();if(parts[0]==='chapter'&&parts[1]==='osmos')updateOsmosis(300);if(old!==route){window.scrollTo(0,0);$('#main').focus({preventScroll:true});}if(parts[2]==='test')$('#chapter-questions')?.scrollIntoView({block:'start'});else if(parts[2]?.startsWith('question-'))$('#'+parts[2])?.scrollIntoView({block:'start'});else if(parts[2]?.startsWith('step-'))$('#'+parts[2])?.scrollIntoView({block:'start'});
}
function renderNav(){const p=route.split('/')[0];const items=[['home','Överblick','home',['home']],['plan','Studieplan','plan',['plan','session','diagnostic']],['course','Kursen','book',['course','chapter']],['exams','Provträning','pen',['exams','exam','variation','exit-check']],['connections','Samband','link',['connections','connection']],['review','Repetition','repeat',['review','progress']]];$('#nav').innerHTML=items.map(([path,label,ico,active])=>`<a href="#${path}" class="${active.includes(p)?'active':''}" ${active.includes(p)?'aria-current="page"':''}>${icon(ico)}<span class="nav-text">${label}</span>${path==='review'?`<span class="nav-count">${E.dueCards(state,C).length}</span>`:''}</a>`).join('')+`<a href="#progress" class="${p==='progress'?'active':''}" style="${window.innerWidth<=900?'display:none':''}">${icon('check')}<span class="nav-text">Mina luckor</span></a>`;}
function updateOsmosis(value){const v=+value;$('#osm-value').textContent=v;const kind=v<300?'hypo':v>300?'hyper':'iso';const r=kind==='hypo'?55:kind==='hyper'?31:43;$('#rbc').setAttribute('rx',r);$('#rbc').setAttribute('ry',kind==='hypo'?50:kind==='hyper'?24:35);$('#rbc-center').setAttribute('rx',kind==='hypo'?35:kind==='hyper'?14:21);$('#rbc-center').setAttribute('ry',kind==='hypo'?32:kind==='hyper'?10:15);const shrink=kind==='hyper'?21:0;const m=$('#plant-membrane');m.setAttribute('x',49+shrink);m.setAttribute('y',33+shrink*.7);m.setAttribute('width',122-2*shrink);m.setAttribute('height',99-1.4*shrink);const vac=$('#vacuole');vac.setAttribute('x',kind==='hyper'?87:kind==='hypo'?57:66);vac.setAttribute('y',kind==='hyper'?59:kind==='hypo'?40:48);vac.setAttribute('width',kind==='hyper'?46:kind==='hypo'?106:88);vac.setAttribute('height',kind==='hyper'?47:kind==='hypo'?85:69);const flow=kind==='hypo'?'Vatten → in':kind==='hyper'?'Vatten → ut':'Inget bestående nettoflöde';$('#rbc-flow').textContent=flow;$('#plant-flow').textContent=kind==='hypo'?'Inflöde → ökad turgor':flow;const msgs={hypo:['Hypoton omgivning','Vatten går först netto in i båda celltyperna. Blodkroppen sväller och kan vid tillräcklig belastning spricka. Växtcellen får högre turgor; väggens mottryck kan till slut balansera drivkraften.'],iso:['Isoton referens','Blodkroppens volym är stabil i den förenklade modellen. Växtcellen är relativt slapp. Vattenmolekyler passerar fortfarande åt båda håll.'],hyper:['Hyperton omgivning','Vatten lämnar cellerna. Blodkroppen krymper; växtcellen tappar turgor och membranet kan dra sig från väggen: plasmolys. Storleken är kvalitativ och inte beräknad från reglaget.']};$('#osm-result').innerHTML=`<h4>${msgs[kind][0]}</h4><p>${msgs[kind][1]}</p>`;}
function repaintCard(id){const c=C.cards.find(x=>x.id===id),el=document.querySelector(`[data-card="${id}"]`);if(c&&el)el.outerHTML=cardHTML(c,route==='diagnostic'||route.startsWith('review'));}
function openSettings(){pauseTimer(false);$('#remaining').value=E.remain(state);$('#focus-length').value=state.focusLength;$('#settings').showModal();}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;switch(action){
  case'settings':openSettings();break;
  case'programme':pauseTimer(false);state.budget=state.studiedSeconds/60+Number(b.dataset.minutes);save();render();toast('Planen utgår nu från '+b.dataset.minutes+' minuter kvar.');break;
  case'day':day=Number(b.dataset.day);render();break;
  case'focus':if(!running)startTimer();toast('Fokustimern är igång. Pauser räknas inte.');break;
  case'show-card':if(shown.has(id)){shown.delete(id);repaintCard(id);break;}if(captureResponse(id))repaintCard(id);break;
  case'unknown-card':captureResponse(id,true);E.rate(state,id,0,Date.now(),state.attempts[id]);save();repaintCard(id);renderNav();break;
  case'rate':{const a=state.attempts[id];if(!a||!shown.has(id))return;E.rate(state,id,Number(b.dataset.rating),Date.now(),a);save();repaintCard(id);renderNav();toast(state.cards[id].rating===2&&!state.cards[id].retainedAt?'Sparat. Återkalla igen efter minst 10 minuter.':'Självskattningen och exakta luckor är sparade.');break;}
  case'diag-back':diagnosticPos=Math.max(0,diagnosticPos-1);render();break;
  case'diag-next':{const ids=['c1','m2','o1','a2','b1','r2','v2'];if(!activeAttempts.has(ids[diagnosticPos])||!state.attempts[ids[diagnosticPos]]?.graded){toast('Välj Inte kan, Delvis kan eller Kan säkert innan du går vidare.');return;}if(diagnosticPos<6){diagnosticPos++;render();}else{state.diagnosed=true;state.tasks.diagnos=true;save();navigate('plan');toast('Diagnosen sparad. Planen prioriterar dina luckor.');}break;}
  case'review-prev':review.pos=Math.max(0,review.pos-1);render();break;
  case'review-next':{const current=review?.ids[review.pos];if(current&&(!activeAttempts.has(current)||!state.attempts[current]?.graded)){toast('Självskatta frågan innan du går vidare.');return;}review.pos++;render();window.scrollTo(0,0);break;}
  case'review-new':shown.clear();preparedResponses.clear();supportViewed.clear();activeAttempts.clear();review=null;render();break;
  case'show-assessment':if(shown.has(id)){shown.delete(id);refreshResponse(id);break;}if(captureResponse(id))refreshResponse(id);break;
  case'support-assessment':captureResponse(id,true);refreshResponse(id);break;
  case'save-assessment':{if(!shown.has(id))return;const a=state.attempts[id];const result=E.finishAssessment(state,C,id,a.checks);save();const el=document.querySelector(`[data-assessment-result="${id}"]`);if(el)el.textContent=`Sparat: ${result.checks.filter(Boolean).length}/${result.checks.length} poänger. Saknade poänger prioriteras i repetitionen.`;toast('Självbedömningen och exakta luckor är sparade.');break;}
  case'fresh-response':freshResponse(id);break;
  case'osm-preset':$('#osm-range').value=b.dataset.value;updateOsmosis(b.dataset.value);break;
  case'pump-next':pumpPos=(pumpPos+1)%pumpSteps.length;$('#pump-lab').innerHTML=pumpLab();break;
  case'pump-prev':pumpPos=Math.max(0,pumpPos-1);$('#pump-lab').innerHTML=pumpLab();break;
}});
document.addEventListener('input',ev=>{const el=ev.target;if(el.dataset.draft){state.drafts[el.dataset.draft]=el.value;save();}if(el.id==='osm-range')updateOsmosis(el.value);if(el.id==='course-search'){courseFilter=el.value;$('#topic-results').innerHTML=filteredChapters();}});
document.addEventListener('change',ev=>{const el=ev.target;if(el.dataset.task){state.tasks[el.dataset.task]=el.checked;save();}if(el.dataset.spoken){el.checked?spoken.add(el.dataset.spoken):spoken.delete(el.dataset.spoken);}if(el.dataset.coreCheck||el.dataset.assessmentCheck){const id=el.dataset.coreCheck||el.dataset.assessmentCheck,a=state.attempts[id];if(a&&!a.assisted){a.checks[Number(el.dataset.index)]=el.checked;if(el.dataset.coreCheck&&state.cards[id]?.rating===2&&!a.checks.every(Boolean))E.rate(state,id,1,Date.now(),a);save();if(el.dataset.coreCheck){const btn=document.querySelector(`[data-action="rate"][data-id="${id}"][data-rating="2"]`);if(btn)btn.disabled=!a.checks.every(Boolean);}}}if(el.id==='review-filter'){reviewFilter=el.value;review=null;shown.clear();render();}if(el.id==='review-chapter'){reviewChapter=el.value;review=null;shown.clear();if(route.split('/')[1])navigate('review');else render();}if(el.id==='exam-chapter'){examFilter=el.value;if(route.split('/')[1])navigate('exams');else render();}});
document.addEventListener('toggle',ev=>{const d=ev.target;if(d.dataset?.previous&&d.open){const id=d.dataset.previous;supportViewed.add(id);const msg=document.querySelector(`[data-attempt-hint="${id}"]`);if(msg)msg.textContent='Tidigare svar har visats. Gör ett nytt tomt försök för att testa utan stöd.';}},true);
$('.skip').addEventListener('click',ev=>{ev.preventDefault();$('#main').focus();});
$('#settings-open').addEventListener('click',openSettings);
$('#remaining-save').addEventListener('click',()=>{const n=Number($('#remaining').value);if(!Number.isFinite(n)||n<5||n>1440){toast('Ange 5–1440 effektiva minuter.');return;}state.budget=state.studiedSeconds/60+n;state.focusLength=Number($('#focus-length').value);timerLeft=state.focusLength*60;save();updateTimer();$('#settings').close();review=null;render();toast('Din tidsbudget är uppdaterad.');});
$('#focus-length').addEventListener('change',()=>{state.focusLength=Number($('#focus-length').value);pauseTimer(false);timerLeft=state.focusLength*60;save();updateTimer();});
function download(name,text){const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#export').addEventListener('click',()=>{save();download('biologi2-framsteg.json',JSON.stringify(state,null,2));toast('Säkerhetskopian har exporterats.');});
$('#import').addEventListener('change',async ev=>{const f=ev.target.files[0];if(!f)return;try{if(f.size>1500000)throw Error('Filen är för stor. Välj en säkerhetskopia från kursen.');const next=E.validateImport(JSON.parse(await f.text()),C);if(!confirm('Ersätt den lokala progressionen med säkerhetskopian? Exportera först om du vill behålla båda.'))return;pauseTimer(false);state=next;review=null;shown.clear();preparedResponses.clear();supportViewed.clear();activeAttempts.clear();examChecks={};timerLeft=state.focusLength*60;save();render();updateTimer();$('#settings').close();toast('Säkerhetskopian har importerats.');}catch(error){toast(error.message||'Kunde inte läsa filen.');}finally{ev.target.value='';}});
$('#reset-progress').addEventListener('click',()=>{if(!confirm('Radera alla dina sparade svar och markeringar på den här adressen?'))return;pauseTimer(false);state=E.fresh();review=null;shown.clear();spoken.clear();preparedResponses.clear();supportViewed.clear();activeAttempts.clear();examChecks={};diagnosticPos=0;timerLeft=25*60;save();$('#settings').close();navigate('home');render();updateTimer();toast('Den lokala progressionen har raderats.');});
let timerLeft=state.focusLength*60,running=false,lastTick=0,timerInterval=null;
function updateTimer(){const n=Math.max(0,Math.ceil(timerLeft));$('#timer-display').textContent=String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');$('#timer-toggle').textContent=running?'Ⅱ':'▶';$('#timer-toggle').setAttribute('aria-label',running?'Pausa fokustimer':'Starta fokustimer');}
function tick(){if(!running)return;const now=performance.now();const delta=Math.min((now-lastTick)/1000,timerLeft);lastTick=now;if(document.hidden){pauseTimer(true);return;}timerLeft-=delta;state.studiedSeconds+=delta;updateTimer();document.querySelectorAll('[data-remaining-display]').forEach(el=>el.textContent=formatMinutes(E.remain(state)));if(timerLeft<=0){pauseTimer(false);toast('Fokusblocket är klart. Ta en paus och återkalla sedan en sak utan stöd.');}if(Math.floor(state.studiedSeconds)%5===0)save();}
function startTimer(){if(timerLeft<=0)timerLeft=state.focusLength*60;running=true;lastTick=performance.now();clearInterval(timerInterval);timerInterval=setInterval(tick,250);updateTimer();}
function pauseTimer(tell){if(running){running=false;clearInterval(timerInterval);save();updateTimer();if(tell)toast('Timern pausades när du lämnade sidan.');}}
$('#timer-toggle').addEventListener('click',()=>running?pauseTimer(false):startTimer());$('#timer-reset').addEventListener('click',()=>{pauseTimer(false);timerLeft=state.focusLength*60;updateTimer();});
document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseTimer(true);});window.addEventListener('beforeunload',()=>{pauseTimer(false);save();});
window.addEventListener('hashchange',()=>{shown.clear();spoken.clear();preparedResponses.clear();supportViewed.clear();activeAttempts.clear();if(!location.hash.startsWith('#review'))review=null;render();});
window.addEventListener('resize',renderNav);render();updateTimer();
})();
